/// 目录 / 榜单 / 书架共用的作品卡片
class NovelCard {
  final String id;
  final String title;
  final String authorName;
  final String authorPeer;
  final String genre;
  final String genreName;
  final List<String> tags;
  final String synopsis;

  /// 卡片的「醒目语」—— 从简介里取出的第一句话。
  /// 本站不做封面（见 README），信息层级是「书名 › 醒目语 › 分类标签 › 统计数字」。
  final String tagline;
  final String status;
  final int episodes;
  final int words;
  final String firstPublishedAt;
  final String updatedAt;

  /// HLC 里的物理时间（毫秒），榜单与排序用它，避免反复解析字符串
