class WrapCoverageView {
  /// 桥接配置是否齐全（peerId + https apiUrl + 合约地址）
  final bool configured;

  /// 配置项自检失败的原因（空 = 通过）
  final List<String> configErrors;
  final String peerId;

  /// 站内余额（收到的 - 转出的 - 已上链锁定的）
  final int balance;

  /// 已被 reward.wrap 消费掉的量
  final int wrapped;

  /// 本机账本里还能上链的量（尚未扣掉节点侧已经花掉的）
  final int available;

  /// 尚未传播到桥接节点的量（节点侧可上链额度低于本机时）
  final int pending;
  final bool nodeReachable;
  final int nodeTotal;
  final int nodeAvailable;
  final int nodeWrapped;
  final List<WrappableOpView> ops;

  const WrapCoverageView({
    required this.configured,
    required this.configErrors,
    required this.peerId,
    required this.balance,
    required this.wrapped,
    required this.available,
    required this.pending,
    required this.nodeReachable,
    required this.nodeTotal,
    required this.nodeAvailable,
    required this.nodeWrapped,
    required this.ops,
  });

  @override
  int get hashCode =>
      configured.hashCode ^
      configErrors.hashCode ^
      peerId.hashCode ^
      balance.hashCode ^
      wrapped.hashCode ^
      available.hashCode ^
      pending.hashCode ^
      nodeReachable.hashCode ^
      nodeTotal.hashCode ^
      nodeAvailable.hashCode ^
      nodeWrapped.hashCode ^
      ops.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WrapCoverageView &&
          runtimeType == other.runtimeType &&
          configured == other.configured &&
          configErrors == other.configErrors &&
          peerId == other.peerId &&
          balance == other.balance &&
          wrapped == other.wrapped &&
          available == other.available &&
          pending == other.pending &&
          nodeReachable == other.nodeReachable &&
          nodeTotal == other.nodeTotal &&
          nodeAvailable == other.nodeAvailable &&
          nodeWrapped == other.nodeWrapped &&
          ops == other.ops;
}

